/// 灵棋经以 (u, m, d) 三层正面数确定 125 卦，完整查表
pub fn get_lingqi_gua(u: u8, m: u8, d: u8) -> LingqiResult {
    let entry = LINGQI_TABLE
        .iter()
        .find(|(eu, em, ed, ..)| *eu == u && *em == m && *ed == d)
        .unwrap_or(&LINGQI_TABLE[124]); // fallback: 纯阴鏝卦

    let (_eu, _em, _ed, gua_id, name, xiang, attr, yao, ke, shi) = *entry;

    LingqiResult {
        gua_id,
        name,
        xiang,
        counts: [u, m, d],
        yinyang_attr: attr,
        yao_ci: yao,
        duan_ci: ke,
        poem: shi,
    }
}

/// 摇棋起卦（输入三层正面棋子数 0~4）
pub fn calculate_lingqi(upper: u8, middle: u8, lower: u8) -> LingqiResult {
    let u = upper.min(4);
    let m = middle.min(4);
    let d = lower.min(4);
    get_lingqi_gua(u, m, d)
}
